// The byte i of the vector of words w0 to w3, or 0 if i is 16 or more
// (i8x16.swizzle).
//
//go:nosplit
func lane_byte(w0, w1, w2, w3 uint32, i uint8) uint8 {
	w := w0
	switch i >> 2 {
	case 0:
	case 1:
		w = w1
	case 2:
		w = w2
	case 3:
		w = w3
	default:
		return 0
	}
	return uint8(w >> (8 * (i & 3)))
}
